FIELD = 'paginate'
DEFAULT = True

def _clean(layer):
    patch = {k: v for k, v in layer.items() if k == FIELD and layer.get(FIELD) is not None}
    return patch

def handle(request):
    output = {FIELD: DEFAULT}
    for layer in (request["tenant"], request["request"]):
        output.update(_clean(layer))
    return {"renderer": output}

